```c++

/*
语法：primetable(n,prime)

头文件：stdio.h string.h

参数：
m：求小于等于n的素数的个数中的n
prime：存素数的数组
返回值：null

*/

/*求小于等于n的素数的个数*/
int prime[100001];//存素数 
void primetable(int n,int prime[])
{
    int cnt = 0;
    bool vis[100001];//保证不做素数的倍数 
    memset(vis, false, sizeof(vis));//初始化 
    memset(prime, 0, sizeof(prime));
    for(int i = 2; i <= n; i++)
    {
        if(!vis[i])//不是目前找到的素数的倍数 
        prime[cnt++] = i;//找到素数~ 
        for(int j = 0; j<cnt && i*prime[j]<=n; j++)
        {
            vis[i*prime[j]] = true;//找到的素数的倍数不访问 
            if(i % prime[j] == 0) break;//关键！！！！ 
        }
    }
    printf("%d\\n", cnt);
}
```


## 求排列组合数

```c++
/*
语法：result=P(long n,long m); / result=long C(long n,long m);

参数：
m：排列组合的上系数
n：排列组合的下系数
返回值：排列组合数

注意：
符合数学规则：m<＝n
*/
long P(long n,long m)
{
    long p=1;
    while(m!=0)
        {p*=n;n--;m--;}
    return p;
} 

long C(long n,long m)
{
    long i,c=1;
    i=m;
    while(i!=0)
        {c*=n;n--;i--;}
    while(m!=0)
        {c/=m;m--;}
    return c;
} 
```

## 行列式计算


```c++
/*
语法：result=js(int s[][],int n)

参数：
s[][]：行列式存储数组
n：行列式维数，递归用
返回值：行列式值

注意：函数中常数N为行列式维度，需自行定义
*/

int s[][N],n; 
int js(s,n) {
    int z,j,k,r,total=0; 
    int b[N][N]; 
    if(n>2)
        {
        for(z=0;z<n;z++) 
            {
            for(j=0;j<n-1;j++) 
                 for(k=0;k<n-1;k++){
                        if(k>=z) b[j][k]=s[j+1][k+1]; 
                        else b[j][k]=s[j+1][k];
                        }
            if(z%2==0) r=s[0][z]*js(b,n-1);  
            else r=(-1)*s[0][z]*js(b,n-1); 
            total=total+r; 
            } 
        } 
    else if(n==2)
       total=s[0][0]*s[1][1]-s[0][1]*s[1][0]; 
    return total; 
} 
```

## Ronberg算法计算积分

```C++
/*
语法：result=integral(double a,double b);

头文件：math.h

参数：
a：积分上限
b：积分下限
function f：积分函数
返回值：f在（a,b）之间的积分值

注意：
function f(x)需要自行修改，程序中用的是sina(x)/x
默认精度要求是1e-5
*/
double f(double x)
{ 
    return sin(x)/x; //在这里插入被积函数 
}

double integral(double a,double b) 
{ 
    double h=b-a; 
    double t1=(1+f(b))*h/2.0;
    int k=1; 
    double r1,r2,s1,s2,c1,c2,t2; 
loop: 
    double s=0.0; 
    double x=a+h/2.0; 
    while(x<b) 
        { 
        s+=f(x); 
        x+=h; 
        } 
    t2=(t1+h*s)/2.0;
    s2=t2+(t2-t1)/3.0;
    if(k==1)
      { 
        k++;h/=2.0;t1=t2;s1=s2;
        goto loop; 
        } 
    c2=s2+(s2-s1)/15.0; 
    if(k==2){ 
        c1=c2;k++;h/=2.0; 
        t1=t2;s1=s2; 
        goto loop; 
        } 
    r2=c2+(c2-c1)/63.0; 
    if(k==3){ 
        r1=r2; c1=c2;k++; 
        h/=2.0; 
        t1=t2;s1=s2;
        goto loop; 
        } 
    while(fabs(1-r1/r2)>1e-5){ 
        r1=r2;c1=c2;k++;
        h/=2.0; 
        t1=t2;s1=s2; 
        goto loop; 
        } 
    return r2;
} 
```

## 组合序列

```c++

/*
语法：m_of_n(int m, int n1, int m1, int* a, int head)

参数：
m：组合数C的上参数
n1：组合数C的下参数
m1：组合数C的上参数，递归之用
*a：1～n的整数序列数组
head：头指针

返回值：null

注意：*a需要自行产生
初始调用时，m=m1、head=0
调用例子：求C(m,n)序列：m_of_n(m,n,m,a,0);
*/

void m_of_n(int m, int n1, int m1, int* a, int head) 
{ 
    int i,t; 
    if(m1<0 || m1>n1) return; 

    if(m1==n1) 
        { 
        for(i=0;i<m;i++) cout<<a[i]<<' '; // 输出序列 
        cout<<'\\n'; 
        return; 
        } 
    m_of_n(m,n1-1,m1,a,head); // 递归调用 
    t=a[head];a[head]=a[n1-1+head];a[n1-1+head]=t;
    m_of_n(m,n1-1,m1-1,a,head+1); // 再次递归调用 
    t=a[head];a[head]=a[n1-1+head];a[n1-1+head]=t;
} 
```


## 最大公约数、最小公倍数

```c++
/*
语法：resulet=hcf(int a,int b)、result=lcd(int a,int b)

参数：
a：int a，求最大公约数或最小公倍数
b：int b，求最大公约数或最小公倍数

返回值：返回最大公约数（hcf）或最小公倍数（lcd）

注意：lcd 需要连同 hcf 使用
*/

int hcf(int a,int b)
{
    int r=0;
    while(b!=0)
        {
        r=a%b;
        a=b;
        b=r;
        }
    return(a);
} 

lcd(int u,int v,int h)
{
    return(u*v/h);
}


```


## 任意进制转换

```c++
/*
语法：conversion(char s1[],char s2[],long d1,long d2);

参数：
s[]：原进制数字，用字符串表示
s2[]：转换结果，用字符串表示
d1：原进制数
d2：需要转换到的进制数

返回值：
null

注意：
高于9的位数用大写'A'～'Z'表示，2～16位进制通过验证
*/
void conversion(char s[],char s2[],long d1,long d2)
{
    long i,j,t,num;
    char c;
    num=0;
    for (i=0;s[i]!='\\0';i++)
        {
        if (s[i]<='9'&&s[i]>='0') t=s[i]-'0'; else t=s[i]-'A'+10;
        num=num*d1+t;
        }
    i=0;
    while(1)
        {
        t=num;
        if (t<=9) s2[i]=t+'0'; else s2[i]=t+'A'-10;
        num/=d2;
        if (num==0) break;
        i++;
        }
    for (j=0;j<i/2;j++)
        {c=s2[j];s2[j]=s[i-j];s2[i-j]=c;}
    s2[i+1]='\\0';
}
```

