/*
  语法：int compare(char a[],char b[]);

      参数： 
      a[]：被比较数，用字符串表示，位数不限
      b[]：比较数，用字符串表示，位数不限

      返回值: 
      0    a<b
      1    a>b
      2    a=b
*/

int compare(char a[], char b[])  
{  
    int lena=strlen(a);  
    int lenb=strlen(b);  
    if(lena>lenb)  
        return 1;  
    else if(lena<lenb)  
        return 0;  
    for(int i=0;i<lena;i++)  
    {  
        if(a[i]>b[i])  
            return 1;  
        else if(a[i]<b[i])  
            return 0;  
    }  
    return 2;  
} 
